import { Component, signal, effect } from '@angular/core';

// ❌ OLD: An effect reads the source and writes the selection signal.
// This works but is fragile: the effect runs on ANY dependency change
// (including the user's own selection write, if the effect reads it),
// can clobber a manual selection, and ordering/loop bugs are easy.
@Component({
  selector: 'app-selector',
  template: `<p>Selected: {{ selectedId() }}</p>`,
})
export class SelectorComponent {
  items = signal([{ id: 'a' }, { id: 'b' }]);
  selectedId = signal(''); // ❌ OLD: independent signal

  constructor() {
    // ❌ OLD: manual re-sync — if the effect also reads selectedId(), it
    // can loop; if it runs after a manual set, it overrides the user.
    effect(() => this.selectedId.set(this.items()[0]?.id ?? ''));
  }
}

import { Component, signal, linkedSignal } from '@angular/core';

// ✅ NEW: linkedSignal derives the selection from the source (first
// item id) and lets the user override it with set(). When the source
// changes (items() recomputes to a different first id), the selection
// re-syncs automatically — no effect, no loops, no clobbering.
@Component({
  selector: 'app-selector',
  template: `<p>Selected: {{ selectedId() }}</p>`,
})
export class SelectorComponent {
  items = signal([{ id: 'a' }, { id: 'b' }]);
  // ✅ NEW: source-linked mutable state
  selectedId = linkedSignal(() => this.items()[0]?.id ?? '');

  pick(id: string) {
    this.selectedId.set(id); // ✅ NEW: user override, respected until source changes
  }
}
